import type {
  GameManifest,
  GameProgressSummary,
  GuidedRoute,
  HubGameEntry,
  MapMarker,
  MapRegion,
} from '../../types/schema';

/**
 * Auto-discovery via Vite import.meta.glob:
 * Any new `src/data/games/<slug>/manifest.json` (and optional `markers.json` / `guides.json`)
 * generated by `npm run add-game` is registered automatically without manual edits.
 */
const manifestModules = import.meta.glob<{ default: GameManifest }>(
  './*/manifest.json',
  { eager: true }
);

const markerModules = import.meta.glob<{ default: MapMarker[] }>(
  './*/markers.json',
  { eager: true }
);

const guideModules = import.meta.glob<{ default: GuidedRoute[] }>(
  './*/guides.json',
  { eager: true }
);

const regionModules = import.meta.glob<{ default: MapRegion[] }>(
  './*/regions.json',
  { eager: true }
);

function extractSlugFromGlobPath(globPath: string): string {
  const parts = globPath.split('/');
  return parts[1] ?? '';
}

export const GAME_MANIFESTS: GameManifest[] = Object.values(manifestModules)
  .map((mod) => mod.default)
  .sort((a, b) => a.title.localeCompare(b.title, 'pt-BR'));

const markersBySlug: Record<string, MapMarker[]> = {};
for (const [globPath, mod] of Object.entries(markerModules)) {
  const slug = extractSlugFromGlobPath(globPath);
  if (slug) {
    markersBySlug[slug] = mod.default as unknown as MapMarker[];
  }
}

const guidesBySlug: Record<string, GuidedRoute[]> = {};
for (const [globPath, mod] of Object.entries(guideModules)) {
  const slug = extractSlugFromGlobPath(globPath);
  if (slug) {
    guidesBySlug[slug] = mod.default as unknown as GuidedRoute[];
  }
}

const regionsBySlug: Record<string, MapRegion[]> = {};
for (const [globPath, mod] of Object.entries(regionModules)) {
  const slug = extractSlugFromGlobPath(globPath);
  if (slug) {
    regionsBySlug[slug] = mod.default as unknown as MapRegion[];
  }
}

export function getRegionsByGameSlug(slug: string): MapRegion[] {
  return regionsBySlug[slug] ?? [];
}

export function getRegionsByMap(slug: string, mapId: string): MapRegion[] {
  const all = getRegionsByGameSlug(slug);
  return all.filter((region) => !region.mapId || region.mapId === mapId);
}

export function getGuidesByGameSlug(slug: string): GuidedRoute[] {
  return guidesBySlug[slug] ?? [];
}

export function getGuidesByMap(slug: string, mapId: string): GuidedRoute[] {
  return getGuidesByGameSlug(slug).filter((guide) => guide.mapId === mapId);
}

export function buildHubEntries(
  progressBySlug: Record<string, GameProgressSummary>
): HubGameEntry[] {
  return GAME_MANIFESTS.map((manifest) => ({
    manifest,
    progress: progressBySlug[manifest.slug] ?? {
      gameSlug: manifest.slug,
      foundMarkersCount: 0,
      activeLayerId: manifest.maps[0]?.id,
    },
  }));
}

export function getGameManifestBySlug(slug: string): GameManifest | undefined {
  return GAME_MANIFESTS.find((manifest) => manifest.slug === slug);
}

export function getMarkersByGameSlug(slug: string): MapMarker[] {
  return markersBySlug[slug] ?? [];
}

export function getMarkersByMap(slug: string, mapId: string): MapMarker[] {
  return getMarkersByGameSlug(slug).filter((marker) => marker.mapId === mapId);
}

/**
 * Returns the real cataloged markers count for progress tracking (falls back to manifest total).
 */
export function getTotalPinsCount(manifest: GameManifest): number {
  const catalogedCount = getMarkersByGameSlug(manifest.slug).length;
  if (catalogedCount > 0) return catalogedCount;
  return manifest.maps.reduce((sum, mapLayer) => sum + mapLayer.pinsCount, 0);
}

export function getAllGenres(games: HubGameEntry[]): string[] {
  const genreSet = new Set<string>();
  for (const entry of games) {
    for (const genre of entry.manifest.genres) {
      genreSet.add(genre);
    }
  }
  return Array.from(genreSet).sort((a, b) => a.localeCompare(b, 'pt-BR'));
}

export function getCompletionPercent(entry: HubGameEntry): number {
  const totalPins = getTotalPinsCount(entry.manifest);
  if (totalPins <= 0) return 0;
  return Math.min(
    100,
    Math.round((entry.progress.foundMarkersCount / totalPins) * 100)
  );
}

export function getGameStatus(
  entry: HubGameEntry
): 'in-progress' | 'completed' | 'not-started' {
  const percent = getCompletionPercent(entry);
  if (percent >= 100) return 'completed';
  if (percent > 0) return 'in-progress';
  return 'not-started';
}
